from v23.state_encoder import get as _v44_get
from v44.gold_floor import GoldFloorConfig as _V44Config
from v44.gold_floor import build_gold_floor_router as _v44_build

_V44_CONFIG = _V44Config(**{'yarn_third_start': 216, 'yarn_third_enabled': True, 'yarn_third_pet_brunch_veto': True, 'yarn_third_prefixes': (('SMOOTHIE_SHOP', 'SMOOTHIE_SHOP'),), 'bakery_capital_enabled': True, 'bakery_capital_start': 160, 'bakery_capital_second_shops': ('PIZZA_SHOP',), 'bakery_capital_minimum_cows': 3, 'bakery_capital_minimum_sheep': 2, 'bakery_capital_minimum_melons': 10, 'bakery_capital_maximum_geese': 0, 'controller': 'sparse', 'aligned_reorder': True, 'clone_preempt_horizon': 2, 'clone_streak_required': 24, 'clone_distance_threshold': 2.0, 'clone_detection_start': 48, 'clone_maximum_batch': 10, 'clone_active_start': 160, 'clone_requires_current_near': False, 'clone_veto_enabled': True, 'clone_veto_step': 120, 'clone_veto_first_shop': 'BAKERY', 'clone_veto_minimum_sheep': 4, 'clone_veto_maximum_cows': 1, 'clone_veto_minimum_wheat': 8, 'clone_veto_minimum_melons': 7, 'clone_veto_maximum_geese': 0, 'clone_phase_detector': True, 'clone_phase_horizon': 3, 'clone_phase_maximum_batch': 20, 'clone_phase_detection_start': 144, 'clone_phase_detection_stop': 159, 'clone_phase_minimum_excess_units': 2, 'clone_phase_maximum_excess_units': 4, 'clone_phase_future_window': 2, 'clone_phase_items': ('STRAWBERRY', 'MELON', 'MILK', 'WOOL'), 'exposure_preempt': False, 'wheat_market_maker': False, 'terminal_rule': 'collision'})
_V44_POLICY = _v44_build(_V44_ROUTES, _V44_CONFIG)


_HARVEST_SELLABLE = (
    "STRAWBERRY", "MELON", "MILK", "WOOL", "EGG",
    "TOMATO", "CARROT", "WHEAT", "FERTILIZER",
)


def _harvest_get(obj, key, default=None):
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _harvest_shed_access(size):
    half = size // 2
    return {(half - 1, half - 1), (half, half - 1),
            (half - 1, half), (half, half)}


def _harvest_move(position, target, tiles):
    x, y = position
    tx, ty = target
    choices = []
    if tx < x:
        choices.append(("WEST", x - 1, y))
    if tx > x:
        choices.append(("EAST", x + 1, y))
    if ty < y:
        choices.append(("NORTH", x, y - 1))
    if ty > y:
        choices.append(("SOUTH", x, y + 1))
    size = len(tiles)
    for operation, nx, ny in choices:
        if 0 <= nx < size and 0 <= ny < size and tiles[ny][nx] != "LOCKED":
            return [operation]
    return ["PASS"]


def _harvest_terminal_action(obs):
    seat = 1 if int(_harvest_get(obs, "player", 0) or 0) == 1 else 0
    farms = list(_harvest_get(obs, "farms", []) or [])
    farm = farms[seat] if seat < len(farms) else {}
    private = _harvest_get(obs, "private", {}) or {}
    tiles = list(_harvest_get(farm, "tiles", []) or [])
    size = len(tiles)
    positions = [_harvest_get(farm, "farmer", [0, 0]),
                 *list(_harvest_get(farm, "hands", []) or [])]
    inventories = list(_harvest_get(private, "inventories", []) or [])
    inventories.extend({} for _ in range(len(positions) - len(inventories)))
    sheds = _harvest_shed_access(size)
    available = {
        (x, y)
        for y, row in enumerate(tiles)
        for x, tile in enumerate(row)
        if (isinstance(tile, dict) and tile.get("crop") == "WHEAT"
            and int(tile.get("yield_units", 0) or 0) > 0)
    }
    actions = []
    pending = {}
    for raw_position, inventory in zip(positions, inventories):
        position = tuple(raw_position)
        inventory = inventory or {}
        load = sum(max(0, int(value or 0)) for value in inventory.values())
        x, y = position
        tile = tiles[y][x] if 0 <= y < size and 0 <= x < size else None
        if load > 0 and position in sheds:
            unit_action = ["DROP"]
            for item, count in inventory.items():
                if item in _HARVEST_SELLABLE:
                    pending[item] = pending.get(item, 0) + max(0, int(count or 0))
        elif isinstance(tile, dict) and int(tile.get("yield_units", 0) or 0) > 0:
            unit_action = ["HARVEST"]
            available.discard(position)
        elif load > 0:
            target = min(sheds, key=lambda cell: abs(cell[0] - x) + abs(cell[1] - y))
            unit_action = _harvest_move(position, target, tiles)
        elif available:
            target = min(available,
                         key=lambda cell: (abs(cell[0] - x) + abs(cell[1] - y),
                                           cell[1], cell[0]))
            available.discard(target)
            unit_action = _harvest_move(position, target, tiles)
        elif isinstance(tile, dict) and tile.get("fertilizer_available", False):
            unit_action = ["COLLECT_FERTILIZER"]
        else:
            unit_action = ["PASS"]
        actions.append(unit_action)

    shed = dict(_harvest_get(private, "shed", {}) or {})
    for item, count in pending.items():
        shed[item] = int(shed.get(item, 0) or 0) + count
    prices = _harvest_get(_harvest_get(obs, "market", {}) or {}, "prices", {}) or {}
    sells = [
        (int(shed.get(item, 0) or 0) * int(_harvest_get(prices, item, 1) or 1),
         item, int(shed.get(item, 0) or 0))
        for item in _HARVEST_SELLABLE
        if int(shed.get(item, 0) or 0) > 0
    ]
    sells.sort(reverse=True)
    return {
        "farmer": actions[0] if actions else ["PASS"],
        "hands": actions[1:],
        "market": [["SELL", item, quantity] for _, item, quantity in sells[:10]],
    }


def _harvest_final_day_overlay(obs, action, step):
    seat = 1 if int(_harvest_get(obs, "player", 0) or 0) == 1 else 0
    farms = list(_harvest_get(obs, "farms", []) or [])
    farm = farms[seat] if seat < len(farms) else {}
    private = _harvest_get(obs, "private", {}) or {}
    tiles = list(_harvest_get(farm, "tiles", []) or [])
    if not tiles:
        return action
    positions = [_harvest_get(farm, "farmer", [0, 0]),
                 *list(_harvest_get(farm, "hands", []) or [])]
    inventories = list(_harvest_get(private, "inventories", []) or [])
    inventories.extend({} for _ in range(len(positions) - len(inventories)))
    unit_actions = [list((action or {}).get("farmer") or ["PASS"]),
                    *[list(row or ["PASS"]) for row in ((action or {}).get("hands") or [])]]
    unit_actions.extend([["PASS"] for _ in range(len(positions) - len(unit_actions))])
    sheds = _harvest_shed_access(len(tiles))
    available = {
        (x, y)
        for y, row in enumerate(tiles)
        for x, tile in enumerate(row)
        if (isinstance(tile, dict) and tile.get("crop") == "WHEAT"
            and int(tile.get("yield_units", 0) or 0) > 0)
    }
    waste = {"PLANT", "FERTILIZE", "DIG", "BUILD_COOP", "BUILD_PASTURE", "PASS"}
    useful = {"HARVEST", "DROP", "FEED", "CARE", "COLLECT_FERTILIZER", "PICKUP", "PLACE"}
    for index, (raw_position, inventory) in enumerate(zip(positions, inventories)):
        x, y = int(raw_position[0]), int(raw_position[1])
        position = (x, y)
        inventory = inventory or {}
        load = sum(max(0, int(value or 0)) for value in inventory.values())
        tile = tiles[y][x] if 0 <= y < len(tiles) and 0 <= x < len(tiles[y]) else None
        operation = unit_actions[index][0] if unit_actions[index] else "PASS"
        if load > 0:
            if position in sheds:
                unit_actions[index] = ["DROP"]
            else:
                target = min(sheds, key=lambda cell: abs(cell[0] - x) + abs(cell[1] - y))
                unit_actions[index] = _harvest_move(position, target, tiles)
            continue
        return_distance = min(abs(x - sx) + abs(y - sy) for sx, sy in sheds)
        if (isinstance(tile, dict) and tile.get("crop") == "WHEAT"
                and int(tile.get("yield_units", 0) or 0) > 0
                and return_distance + 2 <= 718 - step):
            unit_actions[index] = ["HARVEST"]
            available.discard(position)
            continue
        force_move = step >= 708 and operation not in useful
        if available and (operation in waste or force_move):
            target = min(available,
                         key=lambda cell: (abs(cell[0] - x) + abs(cell[1] - y),
                                           cell[1], cell[0]))
            available.discard(target)
            unit_actions[index] = _harvest_move(position, target, tiles)
    result = {
        "farmer": unit_actions[0] if unit_actions else ["PASS"],
        "hands": unit_actions[1:len(positions)],
        "market": [list(row) for row in ((action or {}).get("market") or [])],
    }
    return result

def agent(obs, configuration=None):
    try:
        step = max(0, int(_harvest_get(obs, "step", 0) or 0))
        base = _V44_POLICY(obs, configuration)
        if step >= 696:
            return _harvest_final_day_overlay(obs, base, step)
        return base
    except Exception:
        seat = 1 if int(_v44_get(obs, "player", 0) or 0) == 1 else 0
        farms = list(_v44_get(obs, "farms", []) or [])
        farm = farms[seat] if seat < len(farms) else {}
        return {
            "farmer": ["PASS"],
            "hands": [["PASS"] for _ in (_v44_get(farm, "hands", []) or [])],
            "market": [],
        }


def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)
